param([string]$CandidateRoot = (Join-Path $PSScriptRoot '..\..\lote-02-gpt'))
$ErrorActionPreference = 'Stop'; $pass=0; $fail=0
function Check($id,$ok,$detail){ if($ok){$script:pass++;"PASS $id $detail"}else{$script:fail++;"FAIL $id $detail"} }
function J($p){Get-Content -Raw -Encoding utf8 $p|ConvertFrom-Json}
try {
 $root=(Resolve-Path $CandidateRoot).Path; $schemaDir=Join-Path $root 'specs\schemas'; $fixtureDir=Join-Path $root 'tests\fixtures'
 $schemas=@(Get-ChildItem $root -Recurse -Filter *.schema.json); Check 'G1-SYN-01' ($schemas.Count -eq 10) "schemas=$($schemas.Count)"
 foreach($s in $schemas){$x=J $s.FullName; Check "G1-DIALECT-$($s.BaseName)" ($x.'$schema' -eq 'https://json-schema.org/draft/2020-12/schema') 'draft-2020-12 declarado'; Check "G1-ID-$($s.BaseName)" (-not [string]::IsNullOrWhiteSpace($x.'$id')) '$id presente'; if($x.properties){foreach($p in $x.properties.psobject.Properties){if($p.Value.'$ref'){Check "G1-REF-$($s.BaseName)-$($p.Name)" (Test-Path (Join-Path $s.DirectoryName $p.Value.'$ref')) $p.Value.'$ref'}}}}
 $m=J (Join-Path $schemaDir 'metadata.schema.json'); $a=J (Join-Path $schemaDir 'approval.schema.json'); $e=J (Join-Path $schemaDir 'evidence.schema.json'); $t=J (Join-Path $schemaDir 'task-context.schema.json'); $u=J (Join-Path $schemaDir 'tool-capability.schema.json')
 $canonical=@('DRAFT','IN_REVIEW','PENDING_APPROVAL','CHANGES_REQUESTED','APPROVED','REJECTED','SUPERSEDED','OBSOLETE'); Check 'G1-CTR01-ENUM' ((@($m.properties.state.enum)-join '|') -eq ($canonical-join '|')) 'estado canônico'; Check 'G1-CTR01-REQUIRED' (@($m.required).Count -eq 10 -and $m.required -contains 'owner') 'metadados obrigatórios'; Check 'G1-CTR02-REQUIRED' ($e.required -contains 'logs' -and $e.required -contains 'reviewer') 'evidência mínima'; Check 'G1-CTR03-REQUIRED' ($t.required -contains 'prohibited_actions' -and $t.required -contains 'approved_baseline') 'contexto mínimo'; Check 'G1-CTR04-ENUM' ($u.properties.status.enum -contains 'TESTED' -and $u.properties.status.enum -contains 'APPROVED') 'habilitação explícita'; Check 'G1-APPROVAL-REQUIRED' ($a.required -contains 'decider' -and $a.required -contains 'justification') 'aprovação identificada'
 $negative=@(@('metadata-missing-owner.json','owner'),@('approval-missing-decider.json','decider'),@('evidence-missing-logs.json','logs'),@('task-context-missing-permissions.json','prohibited_actions')); foreach($n in $negative){$o=J (Join-Path $fixtureDir $n[0]); Check "G1-NEG-$($n[0])" (-not $o.psobject.Properties.Name.Contains($n[1])) "campo ausente: $($n[1])"}
 $badState=J (Join-Path $fixtureDir 'metadata-invalid-state.json'); Check 'G1-NEG-STATE' (-not ($badState.state -in $canonical)) 'comentário anexado ao enum inválido'; $nr=J (Join-Path $fixtureDir 'evidence-not-run.json'); Check 'G1-SEM-NOTRUN' ($nr.result -eq 'NOT_RUN') 'NOT_RUN não é PASS'; $route=J (Join-Path $fixtureDir 'tool-capability-untested-routable.json'); Check 'G1-SEM-ROUTING' ($route.status -notin @('TESTED','APPROVED') -and $route.route_requested) 'cenário exige bloqueio pelo futuro roteador'
 foreach($n in 1..5){$p=J (Join-Path $root "specs\contratos\contrato-0$n.schema.json"); Check "G1-PROFILE-0$n" (@($p.properties.control_refs.items.enum).Count -gt 0) 'perfil tem critérios vinculados'}
} catch { Check 'G1-FATAL' $false $_.Exception.Message }
"SUMMARY PASS=$pass FAIL=$fail"; if($fail -gt 0){exit 1}
